INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa797-96d4-7159-960a-e7b03b810be6'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'Speed, distance and travel graphs', 'Speed links distance and time. On a travel graph the gradient gives speed and the area can give distance.', ARRAY['Average speed uses total distance and total time, never the average of two speeds', 'On a distance-time graph the gradient is the speed', 'On a speed-time graph the area under the graph is the distance travelled', 'A horizontal line on a distance-time graph means the object is stationary']::text[], ARRAY['{"note":"Rearranges to distance = speed x time.","label":"Speed","expression":"speed = distance / time"}'::jsonb, '{"note":"Never average the individual speeds.","label":"Average speed","expression":"average speed = total distance / total time"}'::jsonb, '{"note":"Multiply by 3.6 to convert m/s into km/h.","label":"Unit conversion","expression":"1 m/s = 3.6 km/h"}'::jsonb]::text[], ARRAY['{"steps":["First stage time = 60 / 40 = 1.5 hours","Second stage time = 60 / 60 = 1 hour","Total distance = 120 km and total time = 2.5 hours","Average speed = 120 / 2.5"],"answer":"48 km/h, not 50 km/h","question":"A car travels 60 km at 40 km/h, then a further 60 km at 60 km/h. Find the average speed for the whole journey."}'::jsonb]::text[], ARRAY['{"fix":"Average speed is total distance over total time, which gives 48 km/h.","mistake":"Averaging the two speeds to get 50 km/h."}'::jsonb, '{"fix":"On a distance-time graph the speed is the gradient. The area has no meaning.","mistake":"Finding the area under a distance-time graph."}'::jsonb, '{"fix":"Convert to consistent units before substituting.","mistake":"Mixing units, such as distance in km with time in minutes."}'::jsonb]::text[], ARRAY['Write down what each axis shows before reading any travel graph.', 'For average speed, work out total distance and total time separately first.']::text[], ARRAY['t05']::text[], 203, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T07:19:17.458Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa797-96d4-7182-967a-27541bebc955'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'Map scales and scale drawings', 'A map scale compares map length to actual length. Areas scale by the square of the length scale.', ARRAY['Scale = D_map / D_actual, often rewritten as the representative fraction 1 : n', 'Both lengths must use the same unit before writing 1 : n', 'A_map / A_actual = (D_map / D_actual)^2']::text[], ARRAY['{"note":"Reduce so the map side is 1.","label":"Length scale","expression":"scale = D_map / D_actual = 1 / n"}'::jsonb, '{"note":"Square the length scale factor.","label":"Area scale","expression":"A_map / A_actual = (D_map / D_actual)^2"}'::jsonb]::text[], ARRAY['{"steps":["1 cm represents 200000 cm = 2 km, so n = 2","Actual distance = 18.9 x 2 = 37.8 km","1 cm^2 represents 2^2 = 4 km^2, so map area = 728.6 / 4 = 182.15 cm^2"],"answer":"n = 2; 37.8 km; 182.15 cm^2","question":"A map has scale 1 : 200000. (a) Write as 1 cm : n km. (b) Map distance 18.9 cm. Find actual distance in km. (c) Actual area 728.6 km^2. Find map area in cm^2."}'::jsonb]::text[], ARRAY['{"fix":"Square the length scale: areas scale by n^2.","mistake":"Using the length scale factor directly for an area."}'::jsonb, '{"fix":"Convert both lengths to the same unit before simplifying.","mistake":"Writing 1 : n with mixed units."}'::jsonb]::text[], ARRAY['Convert 1 : n into a convenient unit pair (e.g. 1 cm : 2 km) before area work.', 'Check whether the question asks for length or area; that decides whether you square.']::text[], ARRAY['t10']::text[], 204, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T07:19:17.458Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77d-846f-78bf-9be6-38293f247790'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'Percentage change, profit and loss', 'Percentages are fractions with denominator 100. Most exam marks come from choosing the correct 100% baseline and using multipliers.', ARRAY['Percent rate x base value = percentage amount', 'Increase uses (100% + rate); decrease uses (100% - rate)', 'Reverse percentage: final value is a known percent of the original, so divide by that multiplier']::text[], ARRAY['{"note":"E.g. 8.5% of $7.20 is GST tax.","label":"Percentage of a base","expression":"amount = rate x base"}'::jsonb, '{"note":"Always measure against the previous (original) value.","label":"Percentage change","expression":"change / previous value x 100%"}'::jsonb, '{"note":"For reverse percentages, divide final by that multiplier.","label":"Increase / decrease multiplier","expression":"final = base x (100% +/- rate)"}'::jsonb]::text[], ARRAY['{"steps":["$17.50 is 85% of the original price","Original = 17.50 / 0.85 = 20.588...","Round to nearest cent"],"answer":"$20.59","question":"A pair of shoes costs $17.50 after a 15% discount. Find the price before discount."}'::jsonb, '{"steps":["Previous value = 1298 - 31 = 1267","Percentage increase = 31 / 1267 x 100% = 2.4467...%"],"answer":"2.45%","question":"An index rises from 1267 to 1298 (a change of +31). Find the percentage increase to 3 s.f."}'::jsonb]::text[], ARRAY['{"fix":"Divide by 0.85. Reverse percentages divide by the remaining percent.","mistake":"Multiplying by 1.15 to reverse a 15% discount."}'::jsonb, '{"fix":"Percentage change is always measured against the previous value.","mistake":"Using the new value as the 100% baseline for percentage change."}'::jsonb]::text[], ARRAY['Write down what represents 100% before calculating.', 'On a calculator, key fraction x 100 (not x 100%) when converting to a percentage.']::text[], ARRAY['t01']::text[], 301, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:50:48.807Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77d-846f-78da-8d36-a3c6c5093e2d'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'Simple and compound interest', 'Simple interest adds a fixed amount each period on the original principal. Compound interest recalculates on the new balance each period.', ARRAY['Simple interest per period is constant and based on the original principal', 'Compound interest amount grows each period because interest is earned on the previous total', 'Compound formulas usually give the final amount A; interest earned is A - P']::text[], ARRAY['{"note":"R is the rate as a decimal or percent/100; T is the number of periods.","label":"Simple interest","expression":"I = PRT; A = P(1 + RT)"}'::jsonb, '{"note":"A is the final amount after T compounding periods.","label":"Compound amount","expression":"A = P(1 + r/100)^T"}'::jsonb]::text[], ARRAY['{"steps":["I = 2300 x 0.03 x 2 = 138","A = 2300 + 138 = 2438 (or A = 2300(1 + 0.03 x 2))"],"answer":"Interest $138; amount $2438","question":"Deposit $2300 at 3% simple interest per year. Find the interest and amount after 2 years."}'::jsonb, '{"steps":["After 1 year: 12000 x 1.04 = 12480","After 2 years: 12000 x 1.04^2 = 12979.20"],"answer":"$12979.20","question":"Deposit $12000 at 4% compound interest per year. Find the amount after 2 years."}'::jsonb]::text[], ARRAY['{"fix":"Interest earned = final amount minus the principal.","mistake":"Reporting the compound amount when the question asks for the interest."}'::jsonb, '{"fix":"Compound interest multiplies by (1 + r/100) once per period.","mistake":"Using simple interest when the question says compound."}'::jsonb]::text[], ARRAY['Check whether the question wants the total amount or just the interest.', 'For simple interest, A = P(1 + RT) is often faster than finding I first.']::text[], ARRAY['t02']::text[], 302, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:50:48.807Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa797-96d4-7391-a305-684acbf30080'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'Exchange rates, hire purchase and taxation', 'Convert currencies carefully with the given rate, and treat hire purchase as deposit plus all instalments (often with simple interest on the balance).', ARRAY['Rewrite the exchange rate so the currency you want is on the RHS before multiplying', 'Hire purchase total = deposit + remaining amount + interest (if charged)', 'Tax is charged in bands, so only the income inside each band is taxed at that band''s rate']::text[], ARRAY['{"note":"Invert the given rate if needed, then multiply.","label":"Currency conversion","expression":"new amount = original amount x (units of new per 1 unit of old)"}'::jsonb, '{"note":"Total payable = deposit + remaining amount + interest.","label":"Hire purchase instalment","expression":"instalment = (remaining amount + total interest) / number of instalments"}'::jsonb]::text[], ARRAY['{"steps":["1 EUR = 1/0.64 = 1.5625 SGD","30 EUR = 30 x 1.5625 = 46.875 SGD","Total = 46.875 + 7 = 53.875 SGD"],"answer":"53.88 SGD (2 d.p.)","question":"1 SGD = 0.64 EUR. A present costs 19 EUR + 11 EUR transport, plus 7 SGD import charges. Find the total in SGD."}'::jsonb, '{"steps":["Deposit = 0.4 x 50000 = 20000; remaining = 30000","Interest = 30000 x 0.025 = 750","Monthly instalment = (30000 + 750) / 24 = 1281.25","Total payable = 20000 + 30000 + 750 = 50750"],"answer":"$1281.25 per month; total $50750","question":"A car costs $50000. Deposit 40%, then 24 monthly instalments with 2.5% simple interest on the remaining amount. Find the monthly instalment and total payable."}'::jsonb]::text[], ARRAY['{"fix":"Sanity-check the size, or rewrite the rate so the target currency is on the RHS.","mistake":"Multiplying when you should divide in a currency conversion."}'::jsonb, '{"fix":"Total = deposit + remaining balance + interest charged.","mistake":"Forgetting the deposit or the interest when totalling hire purchase."}'::jsonb, '{"fix":"Only the part of the income inside a band is taxed at that band''s rate.","mistake":"Taxing the whole income at the highest band rate."}'::jsonb]::text[], ARRAY['Write the exchange rate as a fraction and cancel units.', 'Hire purchase always costs at least as much as cash (usually more); use that as a check.']::text[], ARRAY['t01']::text[], 303, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T07:19:17.458Z'::timestamptz) ON CONFLICT (id) DO NOTHING;